pub fn render_memory(state: &InitiativeState) -> String {
    let mut lines: Vec<String> = vec![GENERATED_HEADER.to_owned(), String::new()];
    lines.push(format!(
        "# Promoted to repo memory: {}",
        slug_or_unnamed(state)
    ));
    lines.push(String::new());
    lines.push(format!(
        "Cite these in .sofar/repo.md by qualified handle — `{} M<n>` —",
