        let dir = crate::testing::scratch_dir("warmth");
        let log = dir.join("events.jsonl");
        let mut text = String::new();
        for i in 0..400 {
            text.push_str(&format!(
                "{{\"ts\":\"2026-01-01T00:00:{:02}.000Z\",\"type\":\"note_added\",\"pad\":\"{}\"}}\n",
