        .collect();
    let read_subjects: Vec<NoticeSubject> = read_paths(&hook, &root_str)
        .into_iter()
        .filter(|p| !edited.contains(p))
        .map(|subject| NoticeSubject {
            domain: GuardDomain::Path,
            subject,
            edit: false,
