/// `DEFAULT_CHECK_TIMEOUT_MS`: a check's bound when its decision sets none.
pub const DEFAULT_CHECK_TIMEOUT_MS: f64 = 120_000.0;
/// Stop's bounds (`STOP_CHECK_BUDGET_MS`, `STOP_CHECK_MAX_MS`).
