function candidate(file: string, take?: number): string {
  const bin = BIN!.split(' ')
  const args = ['fold', '--events', file, ...(take !== undefined ? ['--take', String(take)] : [])]
  const r = spawnSync(bin[0]!, [...bin.slice(1), ...args], { encoding: 'utf8', maxBuffer: 1 << 30 })
