                let entry = map.next_value_seed(Fields(ENTRY))?;
                let valid = match entry {
                    Some([Some(Kind::Str(id)), Some(Kind::Str(ts))]) => {
                        if k == self.0 {
                            found = Some((id.into_owned(), ts.into_owned()));
