    #[derive(Default)]
    struct Top<'de> {
        v: Option<Kind<'de>>,
        size: Option<Kind<'de>>,
        mtime: Option<Kind<'de>>,
        offset: Option<Kind<'de>>,
        head: Option<Kind<'de>>,
